import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { Search, FileText, FileSpreadsheet, FileIcon, FileJson, FileImage, FileCode } from "lucide-react"

interface Document {
    id: string
    title: string
    extension: string
    createdAt: string
    editedAt: string
}

const sampleDocuments: Document[] = [
    { id: "1", title: "Project Alpha Specs", extension: "pdf", createdAt: "2023-10-01", editedAt: "2023-10-05" },
    { id: "2", title: "Q4 Financials", extension: "xlsx", createdAt: "2023-10-02", editedAt: "2023-10-10" },
    { id: "3", title: "Meeting Notes", extension: "docx", createdAt: "2023-10-03", editedAt: "2023-10-03" },
    { id: "4", title: "User Research 2024", extension: "pdf", createdAt: "2023-10-12", editedAt: "2023-10-15" },
    { id: "5", title: "Backend Architecture", extension: "png", createdAt: "2023-11-01", editedAt: "2023-11-02" },
    { id: "6", title: "API Documentation", extension: "json", createdAt: "2023-11-05", editedAt: "2023-11-10" },
    { id: "7", title: "Frontend Guidelines", extension: "md", createdAt: "2023-11-08", editedAt: "2023-11-08" },
]

const getFileIcon = (extension: string) => {
    switch (extension) {
        case 'pdf': return <FileText className="text-red-500" size={16} />;
        case 'docx': return <FileText className="text-blue-500" size={16} />;
        case 'xlsx': return <FileSpreadsheet className="text-green-500" size={16} />;
        case 'json': return <FileCode className="text-yellow-500" size={16} />;
        case 'png': return <FileImage className="text-purple-500" size={16} />;
        case 'md': return <FileCode className="text-gray-500" size={16} />;
        default: return <FileIcon className="text-gray-400" size={16} />;
    }
}

export default function VaultPage() {
    return (
        <div className="flex flex-1 flex-col gap-4 p-4 pt-0">
            <div className="flex items-center justify-between space-y-2">
                <h2 className="text-3xl font-bold tracking-tight">Vault</h2>
                <div className="flex items-center space-x-2">
                    <Button>Upload</Button>
                </div>
            </div>
            <div className="flex items-center space-x-2">
                <div className="relative flex-1">
                    <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                    <Input placeholder="Search documents..." className="pl-8" />
                </div>
            </div>
            <div className="rounded-md border">
                <div className="w-full overflow-auto">
                    <table className="w-full caption-bottom text-sm">
                        <thead className="[&_tr]:border-b">
                            <tr className="border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted">
                                <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground [&:has([role=checkbox])]:pr-0">Title</th>
                                <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground [&:has([role=checkbox])]:pr-0">Type</th>
                                <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground [&:has([role=checkbox])]:pr-0">Created</th>
                                <th className="h-12 px-4 text-left align-middle font-medium text-muted-foreground [&:has([role=checkbox])]:pr-0">Edited</th>
                            </tr>
                        </thead>
                        <tbody className="[&_tr:last-child]:border-0">
                            {sampleDocuments.map((doc) => (
                                <tr key={doc.id} className="border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted">
                                    <td className="p-4 align-middle [&:has([role=checkbox])]:pr-0 font-medium whitespace-nowrap">
                                        <div className="flex items-center gap-2">
                                            {getFileIcon(doc.extension)}
                                            {doc.title}
                                        </div>
                                    </td>
                                    <td className="p-4 align-middle [&:has([role=checkbox])]:pr-0">
                                        <span className="inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80 uppercase">
                                            {doc.extension}
                                        </span>
                                    </td>
                                    <td className="p-4 align-middle [&:has([role=checkbox])]:pr-0">{doc.createdAt}</td>
                                    <td className="p-4 align-middle [&:has([role=checkbox])]:pr-0">{doc.editedAt}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    )
}
